import{c as t,Q as a,j as n,m as r}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Concepts and glossary","description":"","frontmatter":{},"headers":[],"relativePath":"user/getting-started/concepts-glossary.md","filePath":"user/getting-started/concepts-glossary.md"}'),s={name:"user/getting-started/concepts-glossary.md"};function o(i,e,h,d,c,l){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="concepts-and-glossary" tabindex="-1">Concepts and glossary <a class="header-anchor" href="#concepts-and-glossary" aria-label="Permalink to &quot;Concepts and glossary&quot;">​</a></h1><p><strong>Audience:</strong> Anyone new to orienteering timing, or new to how Manager models it.</p><p>This page defines the orienteering terms and the Manager-specific concepts used throughout the rest of the documentation. You don&#39;t need to read it end to end — skim it now, then come back when a word in another page is unfamiliar. Where a term has a page of its own, the definition links to it.</p><p>Throughout the docs, <em>italic</em> marks a term defined here.</p><h2 id="orienteering-terms" tabindex="-1">Orienteering terms <a class="header-anchor" href="#orienteering-terms" aria-label="Permalink to &quot;Orienteering terms&quot;">​</a></h2><h3 id="the-event-and-its-people" tabindex="-1">The event and its people <a class="header-anchor" href="#the-event-and-its-people" aria-label="Permalink to &quot;The event and its people&quot;">​</a></h3><p><strong>Event</strong> — the top-level container for a competition: its classes, courses, controls, competitors and results all live inside one event. Manager can hold many events; only one is <em>live</em> at a time.</p><p><strong>Competitor</strong> — an individual participant in the event.</p><p><strong>Club</strong> — the organisation a competitor represents. Clubs are reused across events through the <a href="./../reference/club-registry">Club Registry</a>; competitors can be reused through the <a href="./../reference/competitor-registry">Competitor Registry</a>.</p><p><strong>Class</strong> — the category a competitor enters, such as <strong>M21E</strong> (Men, 21, Elite) or <strong>W18A</strong> (Women, 18, A-grade). Everyone in a class is ranked against each other. A class is assigned one or more <em>courses</em>. See <a href="./../event-setup/classes-and-courses">Classes and courses</a>.</p><p><strong>Ranking</strong> — a competitor&#39;s place on an external ranking list drawn up before the event: a national ranking, a squad&#39;s seeding order, whatever list you were handed. <strong>1 is the best-ranked athlete</strong> and the number gets worse as it grows; someone who isn&#39;t on the list has no ranking at all. It is a <em>place</em>, not a points score — Manager never treats a bigger number as better. Its main use is seeding a <a href="./../event-setup/start-draw#drawing-by-ranking">start draw</a>. Nothing to do with a competitor&#39;s finishing position, which Manager works out from the results. See <a href="./../event-setup/competitors-clubs-teams#ranking">Ranking</a>.</p><h3 id="the-course-and-the-controls" tabindex="-1">The course and the controls <a class="header-anchor" href="#the-course-and-the-controls" aria-label="Permalink to &quot;The course and the controls&quot;">​</a></h3><p><strong>Course</strong> — the physical route a competitor runs: an ordered chain of controls from a <em>start</em> to a <em>finish</em>. Several classes can share one course. See <a href="./../event-setup/classes-and-courses">Classes and courses</a>.</p><p><strong>Control</strong> — a single timing point at a position on the map. A normal control carries a <strong>control code</strong> (the number printed on it and programmed into its unit, e.g. <em>131</em>), which is how a punch is matched to it. See <a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a>.</p><p><strong>Start, finish, check</strong> — special controls that mark, respectively, where timing begins, where it ends, and where competitors confirm their card is clear before starting. Unlike normal controls these are <strong>codeless</strong> — they describe a place on the map, not a code. An event can have <strong>several</strong> of each (e.g. <em>Start 1</em> and <em>Start 2</em> at different locations), and each course picks which start and finish it chains through.</p><p><strong>Punch</strong> — the record that a competitor visited a control. Most punches are <strong>electronic</strong>, written to the competitor&#39;s <em>card</em> either by touching the unit (<em>contact</em>) or by SIAC &quot;air&quot; punching (<em>contactless</em>). A <strong>manual</strong> or pin punch is the needle-and-paper backup used when the electronics fail.</p><p><strong>Split</strong> — the time recorded at an intermediate control, used to show how a competitor&#39;s run is progressing and to compare sections of the course between competitors.</p><p><strong>Leg</strong> — the section of a course between two consecutive controls. (In a relay, <em>leg</em> also means one team member&#39;s whole portion of the team&#39;s course — see below.)</p><h3 id="relays-and-teams" tabindex="-1">Relays and teams <a class="header-anchor" href="#relays-and-teams" aria-label="Permalink to &quot;Relays and teams&quot;">​</a></h3><p><strong>Relay team</strong> — a team whose members each run one <em>leg</em> of the course in sequence, handing over to the next runner. The team&#39;s result is the sum of its legs. See <a href="./../event-setup/relay-events">Relay events</a>.</p><h3 id="multi-stage-events-carnivals" tabindex="-1">Multi-stage events (carnivals) <a class="header-anchor" href="#multi-stage-events-carnivals" aria-label="Permalink to &quot;Multi-stage events (carnivals)&quot;">​</a></h3><p><strong>Multi-stage event</strong> — one competition decided over several races: an Easter 3 Days, a summer carnival, a league. Each race is an ordinary event; the multi-stage event is the container that combines them. Often called a <em>carnival</em>.</p><p><strong>Stage</strong> — one race of a multi-stage event, numbered from 1.</p><p><strong>Standings</strong> — the combined result across the stages: each competitor&#39;s per-stage contributions, a total, and an overall position.</p><p><strong>Chase start</strong> (or <em>pursuit start</em>) — a start list for a later stage where everyone starts at their deficit behind the overall leader, so the first across the line wins.</p><p>See <a href="./../event-setup/multi-stage-events">Multi-stage events</a>.</p><h3 id="knock-out-competitions" tabindex="-1">Knock-out competitions <a class="header-anchor" href="#knock-out-competitions" aria-label="Permalink to &quot;Knock-out competitions&quot;">​</a></h3><p><strong>Knock-out competition</strong> — the other kind of multi-stage event: a sequence of rounds where each round&#39;s field comes from the results of the round before, rather than stages added up. Competitors enter once, into the first round.</p><p><strong>Round</strong> — one phase of a knock-out — Qualification, Quarter Finals, Finals. A round <em>is</em> a stage, and therefore an ordinary event. Rounds run one at a time.</p><p><strong>Heat</strong> — one simultaneously-run group within a round. A heat <em>is</em> a class in that round&#39;s event, with its own course and its own mass start. An A final and a B final are two heats of the Finals round, not two rounds.</p><p><strong>Advancement</strong> — working out a round&#39;s field from an earlier round&#39;s results and writing the entries in. Always previewed, never automatic, and safe to run twice.</p><p><strong>Lucky loser</strong> — somebody who advances on their time across all the heats rather than on their place within one.</p><p><strong>Classification</strong> — the overall knock-out result: how far each competitor got, then where they finished in that round.</p><p>See <a href="./../event-setup/knock-out-competitions">Knock-out competitions</a>.</p><h3 id="competitor-status" tabindex="-1">Competitor status <a class="header-anchor" href="#competitor-status" aria-label="Permalink to &quot;Competitor status&quot;">​</a></h3><p>Every competitor has a <strong>status</strong> that Manager works out automatically as start times pass, punches arrive and cards are downloaded. The common ones:</p><table tabindex="0"><thead><tr><th>Shown as</th><th>Meaning</th></tr></thead><tbody><tr><td><em>(blank)</em></td><td><strong>None</strong> — no result yet.</td></tr><tr><td><strong>On Course</strong></td><td>Started but not yet finished (the orienteering term <em>In Forest</em>).</td></tr><tr><td><strong>OK</strong></td><td>Finished with a valid result.</td></tr><tr><td><strong>MP</strong></td><td>Missing Punch — a required control wasn&#39;t punched.</td></tr><tr><td><strong>DNF</strong></td><td>Did Not Finish.</td></tr><tr><td><strong>DNS</strong></td><td>Did Not Start.</td></tr></tbody></table><p>There are several more (DSQ, OVT, OOC, NT, NP, CAN). For the full list and the rules behind every transition, see <a href="./../reference/status-and-race-time">Status and race time rules</a>.</p><h2 id="mesho-manager-concepts" tabindex="-1">meshO Manager concepts <a class="header-anchor" href="#mesho-manager-concepts" aria-label="Permalink to &quot;meshO Manager concepts&quot;">​</a></h2><p><strong>Server / workstation</strong> — you run Manager on one computer (the <strong>server</strong>); everyone else joins from a browser on the same network. There&#39;s no per-machine install. Event data lives in Manager itself — there&#39;s no separate database — and arrives through imports, manual entry, card downloads and radio punches. See <a href="./../what-is-mesho-manager/">How meshO Manager works</a>.</p><h3 id="the-life-of-an-event" tabindex="-1">The life of an event <a class="header-anchor" href="#the-life-of-an-event" aria-label="Permalink to &quot;The life of an event&quot;">​</a></h3><p>An event moves through a few modes, and what you can do depends on which it&#39;s in:</p><ul><li><strong>Setup mode</strong> — the event is being built. You configure classes, courses, controls, competitors and start times. Downloads and live results don&#39;t happen yet.</li><li><strong>Event in progress</strong> — the event is live. Card downloads work, radio punches flow in, and results calculate in real time. The event date locks, but competitors, classes and start times stay editable so late entries and corrections still work. You enter this with <strong>Start event</strong> and leave it with <strong>Finish event</strong>.</li><li><strong>Event completed</strong> — the event has been finished. The data remains for results and exports. Finishing isn&#39;t final: <strong>Restart event</strong> takes a finished event live again, on any later day, for the competitor who turns up after you&#39;ve closed it off.</li></ul><p>(Two exception states exist: an event left running when Manager closed shows as <strong>interrupted</strong> and can be resumed, and one you choose not to resume becomes <strong>abandoned</strong>. Both can be resumed or marked finished at any time.) See the <a href="./first-event-walkthrough">first-event walkthrough</a> for the lifecycle in practice, and <a href="./../running-the-event/dashboard#restarting-an-event-youve-already-finished">the dashboard</a> for restarting.</p><h3 id="how-timing-data-arrives" tabindex="-1">How timing data arrives <a class="header-anchor" href="#how-timing-data-arrives" aria-label="Permalink to &quot;How timing data arrives&quot;">​</a></h3><p><strong>Card</strong> — the electronic timing chip a competitor carries (a SportIdent or EMIT card). It records a punch at each control. &quot;SI card&quot; refers specifically to the SportIdent brand.</p><p><strong>Card download</strong> — reading a finished competitor&#39;s card at the download desk. This produces the <strong>authoritative</strong> result — the full set of punches, evaluated against the course. See <a href="./../running-the-event/card-download">Downloading cards</a>.</p><p><strong>Radio punch</strong> — a punch sent to Manager <strong>live</strong> over radio as the competitor passes a control, rather than waiting for their card to be downloaded at the finish. Radio punches drive the live picture; the card download confirms it later. See <a href="./../running-the-event/radio-punches">Radio punches</a>.</p><p><strong>Radio control</strong> — a control whose unit reports punches live (via meshO Prime), so runners&#39; progress appears on the Spectator, Leaderboard and Commentary screens as they pass. A class&#39;s radio controls form an <strong>ordered sequence</strong> (radio 1, radio 2, …), and Manager identifies each split by its <strong>position</strong> in that sequence rather than by the control&#39;s code — the same code can appear more than once in a course (for example a butterfly or loop passed twice), so the code alone wouldn&#39;t say which passing it was. See <a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a>.</p><p><strong>meshO Prime</strong> — the field-unit hardware that receives punches from radio controls and feeds them to the server. It plugs into the server computer over USB. See <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</p><p><strong>Replay (test mode)</strong> — a training and testing tool that replays captured event data so you can practise or check a setup without a real event. It&#39;s not something you use during a live event. See <a href="./../running-the-event/dashboard">The event dashboard</a>.</p><h3 id="screens-and-views" tabindex="-1">Screens and views <a class="header-anchor" href="#screens-and-views" aria-label="Permalink to &quot;Screens and views&quot;">​</a></h3><p><strong>Operator UI</strong> — the Manager admin app the event team uses: dashboard, competitors, downloads, settings and so on. This is what most of these docs describe.</p><p><strong>Screens</strong> — the read-only public displays you open in their own browser windows and share to TVs, tablets and phones. They include the <strong>Leaderboard</strong>, the <strong>Commentary</strong> view for the announcer, and the <strong>Spectator / Kiosk</strong> views for the crowd. See <a href="./../screens/creating-screens">Creating Leaderboard screens</a>.</p><p><strong>Leaderboard vs Results</strong> — the <strong>Leaderboard</strong> is the spectator-facing live standings shown on screens; the <strong>Results</strong> page is the operator-facing view of the same data, where you publish and export official results. See <a href="./../after-the-event/results">Results</a>.</p><p><strong>Spectator / Kiosk</strong> — the public, self-serve views where competitors and spectators look up start lists, live progress, splits and results from their own device or an arena kiosk.</p><h3 id="extending-manager" tabindex="-1">Extending Manager <a class="header-anchor" href="#extending-manager" aria-label="Permalink to &quot;Extending Manager&quot;">​</a></h3><p><strong>Extensions</strong> — optional add-ons you install at runtime to add custom tiles and features (for example a dashboard tile). They&#39;re a power-user feature, separate from Manager&#39;s built-in functionality. See <a href="./../advanced/installing-extensions">Installing extensions</a>.</p><h3 id="what-s-shared-vs-per-event" tabindex="-1">What&#39;s shared vs per-event <a class="header-anchor" href="#what-s-shared-vs-per-event" aria-label="Permalink to &quot;What&#39;s shared vs per-event&quot;">​</a></h3><p>Most data — competitors, classes, courses, results — belongs to <strong>one event</strong>. A few things are <strong>shared across all your events</strong>: the <a href="./../reference/club-registry">Club Registry</a> and <a href="./../reference/competitor-registry">Competitor Registry</a> (so you can reuse known clubs and people), and your app-wide <a href="./../reference/settings">Settings</a>. Editing a shared registry affects every event that draws on it; editing event data affects only that event.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../what-is-mesho-manager/">How meshO Manager works</a> — the architecture these terms sit in</li><li><a href="./first-event-walkthrough">Walkthrough: your first event</a> — the concepts in action, end to end</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — the full status list and the rules behind it</li></ul>',62)])])}const p=t(s,[["render",o]]);export{u as __pageData,p as default};
